import { ReactNode, RefObject, useEffect, useState } from 'react';

import punycode from 'punycode.js';
import { c } from 'ttag';

import { PROTON_DOMAINS } from '@proton/shared/lib/constants';
import { isEdge, isIE11 } from '@proton/shared/lib/helpers/browser';
import { getSecondLevelDomain } from '@proton/shared/lib/helpers/url';
import { MailSettings } from '@proton/shared/lib/interfaces';
import isTruthy from '@proton/utils/isTruthy';

import { useModalState } from '../components';
import LinkConfirmationModal from '../components/notifications/LinkConfirmationModal';
import { getHostname, isExternal, isSubDomain } from '../helpers/url';
import { useHandler, useNotifications } from './index';

// Reference : Angular/src/app/utils/directives/linkHandler.js

interface LinkSource {
    raw: string;
    encoded?: string;
}

interface UseLinkHandlerOptions {
    onMailTo?: (src: string) => void;
    startListening?: boolean;
    isOutside?: boolean;
    isPhishingAttempt?: boolean;
}
type UseLinkHandler = (
    wrapperRef: RefObject<HTMLDivElement | undefined>,
    mailSettings?: MailSettings,
    options?: UseLinkHandlerOptions
) => { modal: ReactNode };

const defaultOptions: UseLinkHandlerOptions = {
    startListening: true,
};
export const useLinkHandler: UseLinkHandler = (
    wrapperRef,
    mailSettings,
    { onMailTo, startListening, isOutside, isPhishingAttempt } = defaultOptions
) => {
    const { createNotification } = useNotifications();
    const [link, setLink] = useState<string>();

    const [linkConfirmationModalProps, setLinkConfirmationModalOpen] = useModalState();

    const getSrc = (target: Element): LinkSource => {
        const extract = () => {
            try {
                return { encoded: target.toString() || '', raw: target.getAttribute('href') || '' };
            } catch (e: any) {
                /*
                    Because for Edge/IE11
                    <a href="http://xn--rotonmail-4sg.com" rel="noreferrer nofollow noopener">Protonmail.com</a>
                    will crash --> Unspecified error. ¯\_(ツ)_/¯
                    Don't worry, target.href/getAttribute will crash too ¯\_(ツ)_/¯
                    Ivre, ...
                 */
                const attr = Array.from(target.attributes).find((attr) => (attr || {}).name === 'href');
                return { raw: attr?.nodeValue || '' };
            }
        };

        // Because even the fallback canq crash on IE11/Edge. (Now it's a matter of random env issue...)
        try {
            return extract();
        } catch (e: any) {
            createNotification({
                text: c('Error')
                    .t`This message may contain some link's URL that cannot be properly opened by your current browser.`,
                type: 'error',
            });
            return { raw: '' };
        }
    };

    /**
     * Encode the URL to Remove the punycode from it
     * @param  {String} options.raw     getAttribute('href') -> browser won't encode it
     * @param  {String} options.encoded toString() -> encoded value  USVString
     * @return {String}
     */
    const encoder = async ({ raw = '', encoded }: LinkSource) => {
        // https://en.wikipedia.org/wiki/Punycode#Internationalized_domain_names
        const noEncoding = isIE11() || isEdge() || !/:\/\/xn--/.test(encoded || raw);

        /*
            Fallback, Some browsers don't support USVString at all (IE11, Edge)
            Or when the support is "random".
            Ex: PaleMoon (FF ESR 52) works well BUT for one case, where it's broken cf https://github.com/MoonchildProductions/UXP/issues/1125
            Then when we detect there is no encoding done, we use the lib.
         */
        if (noEncoding) {
            // Sometimes there is a queryParam with https:// inside so, we need to add them too :/
            const [protocol, url = '', ...tracking] = raw.split('://');

            const parser = (input: string) => {
                // Sometimes Blink is enable to decode the URL to convert it again
                const uri = !input.startsWith('%') ? input : decodeURIComponent(input);
                return uri.split('/').map(punycode.toASCII).join('/');
            };

            const newUrl = [url, ...tracking].map(parser).join('://');
            return `${protocol}://${newUrl}`;
        }
        return encoded;
    };

    // eslint-disable-next-line @typescript-eslint/no-misused-promises
    const handleClick = useHandler(async (event: Event) => {
        const originalTarget = event.target as Element;
        const target = originalTarget.closest('a');

        if (!target) {
            return;
        }

        const src = getSrc(target);

        // IE11 and Edge random env bug... (╯°□°）╯︵ ┻━┻
        if (!src) {
            event.preventDefault();
            return false;
        }

        // We only handle anchor that begins with `mailto:`
        if (src.raw.toLowerCase().startsWith('mailto:') && onMailTo) {
            event.preventDefault();
            event.stopPropagation(); // Required for Safari

            /*
             * Open the composer with the given mailto address
             * position isAfter true as the user can choose to set a body
             */
            onMailTo(src.raw);
        }

        const askForConfirmation = mailSettings?.ConfirmLink === undefined ? 1 : mailSettings?.ConfirmLink;
        const hostname = getHostname(src.raw);
        const currentDomain = getSecondLevelDomain(window.location.hostname);

        /*
         * If the modal is already active --- do nothing
         * ex: click on a link, open the modal, inside the continue button is an anchor with the same link.
         */
        if (linkConfirmationModalProps.open) {
            return;
        }

        /*
         * If dealing with anchors, we need to treat them separately because we use URLs with # for searching elements
         */
        if (src.raw.startsWith('#')) {
            const id = src.raw.replace('#', '');
            if (wrapperRef.current) {
                const elementInMail = wrapperRef.current.querySelector(`a[name="${id}"], a[id="${id}"]`);
                if (elementInMail) {
                    elementInMail.scrollIntoView({ behavior: 'smooth', block: 'start' });
                }
            }
            event.preventDefault();
            event.stopPropagation();
            return;
        }

        if (
            (askForConfirmation || isPhishingAttempt) &&
            isExternal(src.raw) &&
            ![...PROTON_DOMAINS, currentDomain]
                .filter(isTruthy) // currentDomain can be null
                .some((domain) => isSubDomain(hostname, domain))
        ) {
            event.preventDefault();
            event.stopPropagation(); // Required for Safari

            const link = await encoder(src);
            setLink(link);

            setLinkConfirmationModalOpen(true);
        }
    });

    useEffect(() => {
        if (startListening === false) {
            return;
        }

        // eslint-disable-next-line @typescript-eslint/no-misused-promises
        wrapperRef.current?.addEventListener('click', handleClick, false);
        return () => {
            // eslint-disable-next-line @typescript-eslint/no-misused-promises
            wrapperRef.current?.removeEventListener('click', handleClick, false);
        };
    }, [startListening, wrapperRef.current]);

    const modal = (
        <LinkConfirmationModal
            link={link}
            isOutside={isOutside}
            isPhishingAttempt={isPhishingAttempt}
            {...linkConfirmationModalProps}
        />
    );

    return { modal };
};

import { getSecondLevelDomain } from '@proton/shared/lib/helpers/url';
import isTruthy from '@proton/utils/isTruthy';

export const isSubDomain = (hostname: string, domain: string) => {
    if (hostname === domain) {
        return true;
    }

    return hostname.endsWith(`.${domain}`);
};

export const getHostname = (url: string) => {
    // The easy way to parse an URL, is to create <a> element.
    // @see: https://gist.github.com/jlong/2428561
    const parser = document.createElement('a');
    parser.href = url;
    return parser.hostname;
};

export const isMailTo = (url: string): boolean => {
    return url.toLowerCase().startsWith('mailto:');
};

export const isExternal = (url: string) => {
    try {
        return window.location.hostname !== getHostname(url) && !isMailTo(url);
    } catch (e: any) {
        /*
         * IE11/Edge are the worst, they crash when they try to parse
         * ex: http://xn--rotonmail-4sg.com
         * so if it does we know it's an external link (⌐■_■)
         */
        return true;
    }
};

export const isURLProtonInternal = (url: string) => {
    const currentDomain = getSecondLevelDomain(window.location.hostname);
    const targetOriginHostname = getHostname(url);

    // Still need to check the current domain otherwise it would not work on proton.local, localhost, etc...
    return ['protonmail.com', currentDomain]
        .filter(isTruthy)
        .some((domain) => isSubDomain(targetOriginHostname, domain));
};

import { getHostname, isExternal, isMailTo, isSubDomain, isURLProtonInternal } from '@proton/components/helpers/url';

describe('isSubDomain', function () {
    it('should detect that same hostname is a subDomain', () => {
        const hostname = 'mail.proton.me';
        expect(isSubDomain(hostname, hostname)).toBeTruthy();
    });

    it('should detect that domain is a subDomain', () => {
        const hostname = 'mail.proton.me';
        const domain = 'proton.me';
        expect(isSubDomain(hostname, domain)).toBeTruthy();
    });

    it('should detect that domain is not a subDomain', () => {
        const hostname = 'mail.proton.me';
        const domain = 'whatever.com';
        expect(isSubDomain(hostname, domain)).toBeFalsy();
    });
});

describe('getHostname', function () {
    it('should give the correct hostname', () => {
        const hostname = 'mail.proton.me';
        const url = `https://${hostname}/u/0/inbox`;
        expect(getHostname(url)).toEqual(hostname);
    });
});

describe('isMailTo', function () {
    it('should detect that the url is a mailto link', () => {
        const url = 'mailto:mail@proton.me';
        expect(isMailTo(url)).toBeTruthy();
    });

    it('should detect that the url is not a mailto link', () => {
        const url = 'https://proton.me';
        expect(isMailTo(url)).toBeFalsy();
    });
});

describe('isExternal', function () {
    const windowHostname = 'mail.proton.me';

    beforeEach(() => {
        global.window = Object.create(window);
        Object.defineProperty(window, 'location', {
            value: {
                hostname: windowHostname,
            },
        });
    });

    it('should detect that the url is not external', () => {
        const url1 = 'https://mail.proton.me';
        expect(window.location.hostname).toEqual(windowHostname);
        expect(isExternal(url1)).toBeFalsy();
    });

    it('should detect that the url is external', () => {
        const url = 'https://url.whatever.com';
        expect(window.location.hostname).toEqual(windowHostname);
        expect(isExternal(url)).toBeTruthy();
    });

    it('should detect that the mailto link is not external', () => {
        const url = 'mailto:mail@proton.me';
        expect(window.location.hostname).toEqual(windowHostname);
        expect(isExternal(url)).toBeFalsy();
    });
});

describe('isProtonInternal', function () {
    const windowHostname = 'mail.proton.me';

    beforeEach(() => {
        global.window = Object.create(window);
        Object.defineProperty(window, 'location', {
            value: {
                hostname: windowHostname,
            },
        });
    });

    it('should detect that the url is proton internal', () => {
        const url1 = 'https://mail.proton.me';
        const url2 = 'https://calendar.proton.me';

        expect(isURLProtonInternal(url1)).toBeTruthy();
        expect(isURLProtonInternal(url2)).toBeTruthy();
    });

    it('should detect that the url is not proton internal', () => {
        const url = 'https://url.whatever.com';

        expect(isURLProtonInternal(url)).toBeFalsy();
    });
});

import { APPS, APPS_CONFIGURATION, APP_NAMES, DOH_DOMAINS, LINK_TYPES } from '../constants';

const PREFIX_TO_TYPE: { [prefix: string]: LINK_TYPES | undefined } = {
    'tel:': LINK_TYPES.PHONE,
    'mailto:': LINK_TYPES.EMAIL,
    'http://': LINK_TYPES.WEB,
    'https://': LINK_TYPES.WEB,
};

const TYPE_TO_PREFIX = {
    [LINK_TYPES.PHONE]: { regex: /^tel:/, defaultPrefix: 'tel:' },
    [LINK_TYPES.EMAIL]: { regex: /^mailto:/, defaultPrefix: 'mailto:' },
    [LINK_TYPES.WEB]: { regex: /^http(|s):\/\//, defaultPrefix: 'https://' },
};

// Create one big regexp of all the regexes in TYPE_TO_PREFIX.
// It can be used for finding a particular type from a link.
const ALL_REGEXP_SOURCES = (Object.keys(TYPE_TO_PREFIX) as LINK_TYPES[])
    .map((key) => `(${TYPE_TO_PREFIX[key].regex.source})`)
    .join('|');

const ALL_REGEXP = new RegExp(ALL_REGEXP_SOURCES);

/**
 * Extract host
 * @param url
 * @returns host
 */
export const getHost = (url = '') => {
    const { host = '' } = new URL(url);
    return host;
};

/**
 * Extract hostname
 * @param url
 * @returns hostname
 */
export const getHostname = (url = '') => {
    const { hostname = '' } = new URL(url);
    return hostname;
};

/**
 * Converts search parameters from hash to a URLSearchParams compatible string
 */
const getSearchFromHash = (search: string) => {
    let searchHash = search;
    if (searchHash) {
        searchHash = searchHash[0] === '#' ? `?${search.slice(1)}` : searchHash;
    }
    return searchHash;
};

export const stringifySearchParams = (params: { [key: string]: string | string[] | undefined }) => {
    const urlSearchParams = new URLSearchParams();

    Object.entries(params)
        .filter(([, value]) => value !== undefined)
        .forEach(([key, value]) => {
            /*
             * typescript is not able to determine that stringifiedValue
             * can't be undefined because of the previous filter condition
             * therefore, typecast to string
             */
            const stringifiedValue = Array.isArray(value) ? value.join(',') : (value as string);

            urlSearchParams.set(key, stringifiedValue);
        });

    return urlSearchParams.toString();
};

/**
 * Return a param (native) map based on the search string
 */
export const getSearchParams = (search: string): { [key: string]: string } => {
    const params = new URLSearchParams(getSearchFromHash(search));

    const result: { [key: string]: string } = {};

    params.forEach((value, key) => {
        result[key] = value;
    });

    return result;
};

/**
 * Return a new pathname with the query string updated from
 * the search input and updated with the newParams
 */
export const changeSearchParams = (
    pathname: string,
    search: string,
    newParams: { [key: string]: string | undefined }
) => {
    const params = new URLSearchParams(getSearchFromHash(search));

    Object.keys(newParams).forEach((key) => {
        if (newParams[key] === undefined) {
            params.delete(key);
        } else {
            params.set(key, newParams[key] as string);
        }
    });

    // Remove potential mailto query from the params, otherwise search will be concatenated to the mailto query
    if (params.get('mailto')) {
        params.delete('mailto');
    }

    const queryString = params.toString();
    const urlFragment = (queryString === '' ? '' : '#') + queryString;

    return pathname + urlFragment;
};

/**
 * Convert from a link prefix to link type.
 */
const prefixToType = (prefix = 'http://') => {
    return PREFIX_TO_TYPE[prefix];
};

/**
 * Get a link prefix from a url.
 */
const getLinkPrefix = (input = ''): string | undefined => {
    const matches = ALL_REGEXP.exec(input) || [];
    return matches[0];
};

/**
 * Get a link type from a link.
 */
export const linkToType = (link = '') => {
    const prefix = getLinkPrefix(link);
    return prefixToType(prefix);
};

/**
 * Strip the link prefix from a url.
 * Leave the prefix if it's http to let the user be able to set http or https.
 */
export const stripLinkPrefix = (input = '') => {
    const prefix = getLinkPrefix(input);
    if (!prefix || prefix.indexOf('http') !== -1) {
        return input;
    }
    return input.replace(prefix, '');
};

/**
 * Try to add link prefix if missing
 */
export const addLinkPrefix = (input = '', type: LINK_TYPES) => {
    const prefix = getLinkPrefix(input);

    if (prefix) {
        return input;
    }

    const { defaultPrefix } = TYPE_TO_PREFIX[type] || {};

    if (defaultPrefix) {
        return `${defaultPrefix}${input}`;
    }

    return input;
};

